export const BANK=[{"id": "QMS-M01-Q001", "module": 1, "objective": "M1-LO1", "level": "Understand", "type": "MCQ", "question": "Which development best describes the shift from inspection-centred quality to quality management?", "options": {"A": "Replacing measured inspection results with customer satisfaction surveys", "B": "Inspecting finished work more often and with stricter acceptance limits", "C": "Managing how work is performed so problems are prevented and recur less", "D": "Moving inspection duties from the workshop to the customer's receiving staff"}, "answer": "C", "feedback": {"C": "Quality management looks at how processes produce results, not only at finished outputs.", "A": "Customer feedback is useful, but modern quality management does not discard measurement.", "B": "More inspection still only checks finished work; it does not explain why problems recur.", "D": "This moves the check elsewhere; it does not change how work is managed."}, "refs": ["R01", "R02"], "locator": "Module 1, §1.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Walter A. Shewhart; ASQ (n.d.), Quality assurance vs quality control · Module 1, §1.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q002", "module": 1, "objective": "M1-LO1", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: Several brackets from one machine are too wide. Which response reflects managing the system rather than only inspecting output?", "options": {"A": "Examine the machine setup and instructions to find the cause", "B": "Widen the drawing tolerance so that fewer brackets are rejected", "C": "Reject the wide brackets and inspect every future part before release", "D": "Record the rejected brackets and wait to see the next batch's results"}, "answer": "A", "feedback": {"A": "Looking for the cause in the process is the step beyond inspection.", "B": "Changing the requirement to fit the output hides the problem; it does not manage it.", "C": "This contains the problem but leaves its cause in place.", "D": "Recording is useful evidence, but waiting does nothing to find the cause."}, "refs": ["R01", "R02"], "locator": "Module 1, §1.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Walter A. Shewhart; ASQ (n.d.), Quality assurance vs quality control · Module 1, §1.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q003", "module": 1, "objective": "M1-LO1", "level": "Remember", "type": "MCQ", "question": "What did Walter A. Shewhart's control chart help practitioners study?", "options": {"A": "How customers rate a service after delivery", "B": "How a process's results vary over time", "C": "Whether one finished part meets its drawing", "D": "Which individual operator caused a defect"}, "answer": "B", "feedback": {"B": "A control chart tracks process variation over time.", "A": "Customer ratings are a different measure; the control chart studies process variation.", "C": "That is a single inspection (QC) result, not process variation over time.", "D": "Control charts describe process behaviour; they are not a tool for assigning individual blame."}, "refs": ["R01", "R02"], "locator": "Module 1, §1.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Walter A. Shewhart; ASQ (n.d.), Quality assurance vs quality control · Module 1, §1.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q004", "module": 1, "objective": "M1-LO2", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A technician compares a repaired part's measured result with its test limits. Which function does this activity most directly illustrate?", "options": {"A": "Quality management", "B": "Quality assurance (QA)", "C": "Quality control (QC)", "D": "Compliance monitoring"}, "answer": "C", "feedback": {"C": "This acceptance check directly illustrates QC. QC concerns fulfilling quality requirements and is not limited to final inspection. QA and QC are both parts of quality management.", "A": "Quality management is the broader category that includes QC; QC is the more specific answer.", "B": "QA focuses on confidence that requirements will be fulfilled; the immediate task here is an acceptance check.", "D": "Compliance monitoring may include product sampling, but no independent compliance-monitoring assessment is described here."}, "refs": ["R02", "R07"], "locator": "Module 1, §1.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Quality assurance vs quality control; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q005", "module": 1, "objective": "M1-LO2", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A reviewer observes technicians on both shifts to check that they use the approved test method. What does this activity mainly provide?", "options": {"A": "Confirmation that each tested part is within its limits", "B": "Confidence that requirements will be met consistently", "C": "Confirmation that the test procedure itself is technically adequate", "D": "A decision on which improvement objective to set next year"}, "answer": "B", "feedback": {"B": "The observation provides QA evidence about consistent use of the method. It does not establish that every output conforms. The same observation could support compliance monitoring if performed for that purpose against applicable criteria.", "A": "Observing method use is different from checking every test result.", "C": "Consistent use does not establish that the method is technically adequate; that needs separate evidence.", "D": "The observation can inform objectives, but does not itself set them."}, "refs": ["R02", "R07"], "locator": "Module 1, §1.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Quality assurance vs quality control; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q006", "module": 1, "objective": "M1-LO2", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: At the monthly review, a station manager sees that 8 of 40 flights missed the 20-minute baggage target, names an investigation lead and schedules a follow-up review. Which function does this management response most directly illustrate?", "options": {"A": "Quality assurance (QA)", "B": "Quality control (QC)", "C": "Quality management", "D": "Compliance monitoring"}, "answer": "C", "feedback": {"C": "Assigning responsibility, investigating and planning to check results is quality management.", "A": "QA evidence can inform this review, but assigning responsibility and following up are broader management activities.", "B": "Measuring performance against the target can support QC; this question emphasises the management response.", "D": "Compliance monitoring can assess applicable requirements, policies and procedures; the scenario describes management review, not a compliance-monitoring assessment."}, "refs": ["R02", "R07"], "locator": "Module 1, §1.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Quality assurance vs quality control; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q007", "module": 1, "objective": "M1-LO3", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A workshop wants to agree on what “corrective action” means before writing its procedures. Which standard should it consult?", "options": {"A": "ISO 9000", "B": "ISO 9004", "C": "ISO 9001", "D": "ISO 19011"}, "answer": "A", "feedback": {"A": "ISO 9000 sets out the fundamentals and vocabulary of quality management.", "B": "ISO 9004 gives guidance on sustained organisational success, not the vocabulary.", "C": "ISO 9001 specifies QMS requirements; ISO 9000 is the dedicated fundamentals and vocabulary reference.", "D": "ISO 19011 gives guidance on auditing management systems."}, "refs": ["R03", "R04", "R05", "R14"], "locator": "Module 1, §1.4", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; ISO (2026), ISO 9001:2026: What businesses need to know; ISO (2026), ISO 19011:2026; ISO (2018), ISO 9004:2018 · Module 1, §1.4", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q008", "module": 1, "objective": "M1-LO3", "level": "Remember", "type": "MCQ", "question": "Which statement correctly describes ISO 9001:2026?", "options": {"A": "It sets approval conditions for repair organisations", "B": "It gives guidance on auditing management systems", "C": "It defines the vocabulary used in the ISO 9000 family", "D": "It specifies requirements for a QMS"}, "answer": "D", "feedback": {"D": "ISO 9001 is the requirements standard of the family.", "A": "Approval conditions come from aviation regulation such as Part-145, not from ISO 9001.", "B": "That is ISO 19011.", "C": "That is ISO 9000."}, "refs": ["R03", "R04", "R05"], "locator": "Module 1, §1.4", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; ISO (2026), ISO 9001:2026: What businesses need to know; ISO (2026), ISO 19011:2026 · Module 1, §1.4", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q009", "module": 1, "objective": "M1-LO3", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: A ground handler holds an ISO 9001 certificate. A customer airline asks whether this means every service is defect-free and all aviation rules are met. Which answer is best supported?", "options": {"A": "No: certification addresses documents without considering implementation", "B": "Yes for the activities listed in the certificate’s scope", "C": "Yes: certification confirms both service quality and aviation compliance", "D": "No: it covers the QMS; outputs and aviation rules need other evidence"}, "answer": "D", "feedback": {"D": "Certification concerns the system; individual outputs and applicable aviation obligations need their own evidence.", "A": "Certification audits examine implementation as well as documentation; their conclusions remain bounded by scope and sampling.", "B": "A defined certification scope does not create an output guarantee.", "C": "System certification does not guarantee every service outcome or demonstrate every aviation obligation."}, "refs": ["R03", "R04", "R05"], "locator": "Module 1, §1.4", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; ISO (2026), ISO 9001:2026: What businesses need to know; ISO (2026), ISO 19011:2026 · Module 1, §1.4", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q010", "module": 1, "objective": "M1-LO4", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: An organisation has an approved QMS manual, but auditors find no records showing that staff follow its procedures. What is the most defensible conclusion?", "options": {"A": "Effectiveness cannot be established from the manual alone", "B": "Treat refresher training as the corrective action without further investigation", "C": "The QMS is effective because the manual has been approved", "D": "Rewrite the procedures before investigating implementation"}, "answer": "A", "feedback": {"A": "An effective QMS depends on implementation and feedback, not only written arrangements.", "B": "Training may be appropriate, but selecting it before investigating assumes the cause.", "C": "Approval shows intended arrangements, not effective implementation.", "D": "The evidence does not yet establish that procedure design is the cause."}, "refs": ["R04", "R06"], "locator": "Module 1, §1.4 and §1.5", "group": "implementation-evidence", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9001:2026: What businesses need to know; ISO (n.d.), Quality management principles · Module 1, §1.4 and §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q011", "module": 1, "objective": "M1-LO4", "level": "Understand", "type": "MCQ", "question": "Which activity shows QMS implementation through organisational action rather than documentation alone?", "options": {"A": "Collecting signatures on the manual's distribution list", "B": "Having an owner review repeat failures and check results", "C": "Publishing a revised quality policy on the company intranet", "D": "Adding a new chapter on rework to the quality manual"}, "answer": "B", "feedback": {"B": "Responsibility, review and follow-up show the system working in practice.", "A": "Signatures show the manual was distributed, not that it is followed.", "C": "Publishing a policy is documentation; it does not show the policy is applied.", "D": "A new chapter documents intentions; it does not show action."}, "refs": ["R04", "R06"], "locator": "Module 1, §1.4 and §1.5", "group": "implementation-evidence", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9001:2026: What businesses need to know; ISO (n.d.), Quality management principles · Module 1, §1.4 and §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q012", "module": 1, "objective": "M1-LO4", "level": "Understand", "type": "True/False", "question": "A detailed, approved QMS manual is enough evidence that a quality management system is implemented effectively.", "options": {"A": "True", "B": "False"}, "answer": "B", "feedback": {"B": "Possessing a manual does not establish effective implementation.", "A": "Not quite. A manual shows intended arrangements; effectiveness needs evidence of implementation and feedback."}, "refs": ["R04", "R06"], "locator": "Module 1, §1.4 and §1.5", "group": "implementation-evidence", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9001:2026: What businesses need to know; ISO (n.d.), Quality management principles · Module 1, §1.4 and §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q013", "module": 1, "objective": "M1-LO5", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: An older procedure refers to the “quality manager”, while the applicable Part-145 text refers to compliance monitoring. What should a reader do?", "options": {"A": "Treat both labels as the same legal function without checking", "B": "Replace every reference with “quality assurance” for consistency", "C": "Follow the older procedure, because it was approved first", "D": "Identify the term used by the regulation and check the function"}, "answer": "D", "feedback": {"D": "Labels vary over time; read the applicable regulation and check what each role actually does.", "A": "Labels do not always describe the same legal function; assuming so can cause errors.", "B": "Quality assurance is a different concept; renaming does not resolve the question.", "C": "The applicable regulation governs; an older internal label does not override it."}, "refs": ["R07"], "locator": "Module 1, §1.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q014", "module": 1, "objective": "M1-LO5", "level": "Remember", "type": "MCQ", "question": "In the EASA Part-145 management-system framework, which term describes checking that the organisation meets the relevant requirements?", "options": {"A": "Compliance monitoring", "B": "Quality inspection programme", "C": "Quality control", "D": "Quality assurance"}, "answer": "A", "feedback": {"A": "145.A.200 uses compliance monitoring.", "B": "This is not the term used for the function in 145.A.200(a)(6).", "C": "QC is concerned with fulfilling quality requirements; it is not the name of the Part-145 monitoring function.", "D": "QA and compliance monitoring can overlap in practice, but compliance monitoring is the regulatory term asked for."}, "refs": ["R07"], "locator": "Module 1, §1.5", "group": "part145-term", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q015", "module": 1, "objective": "M1-LO5", "level": "Remember", "type": "True/False", "question": "The EASA Part-145 management-system framework uses the term compliance monitoring.", "options": {"A": "True", "B": "False"}, "answer": "A", "feedback": {"A": "145.A.200 uses compliance monitoring; older documents may say quality assurance.", "B": "Not quite. Part-145 does use compliance monitoring, even if older job titles say quality manager."}, "refs": ["R07"], "locator": "Module 1, §1.5", "group": "part145-term", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q016", "module": 1, "objective": "M1-LO2", "level": "Apply", "type": "Matching", "question": "Match each activity to the function it most directly illustrates in this exercise. Functions may overlap; select the most specific description of the stated purpose.", "pairs": [["Measuring one repaired part against its test limits", "Quality control (QC)"], ["Observing technicians on both shifts using the approved test method", "Quality assurance (QA)"], ["Assigning an investigation of repeat rework and scheduling a results review", "Quality management"], ["Checking the organisation against the applicable Part-145 requirements", "Compliance monitoring"]], "distractors": ["Accident investigation"], "feedback": "The acceptance test most directly illustrates QC; the method observation provides QA evidence; assigning an investigation and reviewing results illustrates broader quality management; the Part-145 assessment illustrates compliance monitoring. QA and QC are parts of quality management. These functions can overlap: an observation or product sample can also support compliance monitoring when used for that purpose. Accident investigation principally supports prevention through examination of causes and circumstances.", "refs": ["R02", "R07"], "locator": "Module 1, §1.3 and §1.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), Quality assurance vs quality control; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 1, §1.3 and §1.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q017", "module": 1, "objective": "M1-LO3", "level": "Apply", "type": "Fill-in-the-blank", "question": "Illustrative scenario: A Part-145 workshop is drafting its internal audit procedure. Two staff disagree about what the term “corrective action” means, and the quality manager must also confirm what the QMS is required to contain. To settle the meaning of the term, the workshop should consult ISO ____; to confirm the requirement, it consults ISO 9001.", "answers": ["9000", "ISO 9000", "9000:2026", "ISO 9000:2026"], "feedback": "ISO 9000 sets out the fundamentals and vocabulary; ISO 9001 specifies the requirements.", "refs": ["R03", "R04", "R05"], "locator": "Module 1, §1.4", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; ISO (2026), ISO 9001:2026: What businesses need to know; ISO (2026), ISO 19011:2026 · Module 1, §1.4", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M01-Q018", "module": 1, "objective": "M1-LO4", "level": "Analyse", "type": "Short answer", "question": "Illustrative scenario: A station’s QMS manual says the manager reviews repeat baggage delays every month. Name one record that would show the review took place and one record that would show whether an action worked. Explain in one sentence why the two records answer different questions.", "model_answer": "Dated review minutes identifying decisions, actions and owners support that the review occurred. Delay rates measured consistently on comparable flights before and after the action, over sufficient follow-up periods, help assess effectiveness. The first concerns implementation; the second concerns results, although other changes may also have affected those results.", "marking_points": ["Names a record of the review itself, e.g., dated minutes with actions", "Names results evidence, e.g., comparable delay rates before and after", "Explains that one shows implementation and the other shows effectiveness"], "accept_note": "Accept equivalent, evidence-supported responses; the model answer is an example, not a required script.", "refs": ["R04", "R06"], "locator": "Module 1, §1.4, §1.5 and learning check 3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9001:2026: What businesses need to know; ISO (n.d.), Quality management principles · Module 1, §1.4, §1.5 and learning check 3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q001", "module": 2, "objective": "M2-LO1", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A station manager compares baggage outcomes using reliable timestamps before choosing a change. Which quality management principle does this apply?", "options": {"A": "Process approach", "B": "Customer focus", "C": "Relationship management", "D": "Evidence-based decision-making"}, "answer": "D", "feedback": {"D": "Decisions are based on analysis of reliable data.", "A": "The process approach concerns managing linked activities; this example is about how the decision is made.", "B": "Customer focus concerns meeting customer needs; the key feature here is basing the decision on data.", "C": "Relationship management concerns suppliers and other interested parties; the key feature here is basing the decision on data."}, "refs": ["R06"], "locator": "Module 2, §2.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q002", "module": 2, "objective": "M2-LO1", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: The airport agrees responsibilities with its contracted ground handler. Which principle does this illustrate?", "options": {"A": "Engagement of people", "B": "Leadership", "C": "Relationship management", "D": "Customer focus"}, "answer": "C", "feedback": {"C": "It concerns managing relationships with interested parties such as suppliers.", "A": "Engagement of people concerns enabling and involving people; the stem focuses on the relationship between organisations.", "B": "Leadership can support the agreement, but managing an external supplier relationship is the main emphasis.", "D": "The contractor relationship can support customer satisfaction, but customer needs are not the direct emphasis of this question."}, "refs": ["R06"], "locator": "Module 2, §2.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q003", "module": 2, "objective": "M2-LO1", "level": "Understand", "type": "MCQ", "question": "Which list contains only quality management principles?", "options": {"A": "Customer focus, leadership, process approach", "B": "Customer focus, certification, process approach", "C": "Improvement, compliance monitoring, relationship management", "D": "Leadership, inspection, evidence-based decision-making"}, "answer": "A", "feedback": {"A": "All three are among the seven principles.", "B": "Certification is not a quality management principle.", "C": "Compliance monitoring is a regulatory function, not a principle.", "D": "Inspection is an activity, not one of the seven principles."}, "refs": ["R06"], "locator": "Module 2, §2.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q004", "module": 2, "objective": "M2-LO2", "level": "Analyse", "type": "MCQ", "question": "Illustrative scenario: The unloading team meets its dispatch target and the belt team meets its processing target, but bags still wait. What does the process approach suggest examining first?", "options": {"A": "Passenger complaints, which show where the delay occurs", "B": "The unloading team's target, which should be made stricter", "C": "The belt team's staffing, since the bags wait at the belt", "D": "The handover between the teams, using matched timestamps"}, "answer": "D", "feedback": {"D": "Check the interface first as a plausible gap, using matched timestamps. Meeting local targets does not prove the interface caused the delay; target definitions, resource constraints and the complete flow still need examination.", "A": "Complaints show that passengers wait, not where in the process the delay arises.", "B": "A stricter target for one team ignores where the bags actually wait.", "C": "This assumes the cause; matched timestamps would show where waiting occurs."}, "refs": ["R06"], "locator": "Module 2, §2.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q005", "module": 2, "objective": "M2-LO2", "level": "Understand", "type": "MCQ", "question": "For one aircraft turnaround, defined here as the operational handling process from arrival to departure readiness, which option is a direct input?", "options": {"A": "The on-time departure recorded after boarding ends", "B": "The passenger satisfaction score collected after the flight", "C": "The arriving aircraft and its handling information", "D": "The monthly delay rate reported to the station manager"}, "answer": "C", "feedback": {"C": "These enter the process and are transformed by its activities.", "A": "This is an operational result, not an incoming input to this turnaround.", "B": "Satisfaction data can inform improvement, but are not the direct operational input asked for.", "D": "Monthly delay data can inform planning and improvement, but are not the direct operational input asked for."}, "refs": ["R06"], "locator": "Module 2, §2.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q006", "module": 2, "objective": "M2-LO2", "level": "Understand", "type": "True/False", "question": "Making one turnaround activity faster always shortens the total turnaround time.", "options": {"A": "True", "B": "False"}, "answer": "B", "feedback": {"B": "Interfaces and constraints elsewhere can absorb the gain.", "A": "Not quite. If another linked activity remains the constraint, the total may not change."}, "refs": ["R06"], "locator": "Module 2, §2.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q007", "module": 2, "objective": "M2-LO3", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A baggage team trials a new handover on selected shifts. Which activity belongs to the Check stage?", "options": {"A": "Setting the baseline and choosing the measure", "B": "Adopting the new handover across all of the shifts", "C": "Testing the new handover on the selected shifts", "D": "Comparing trial results with the baseline"}, "answer": "D", "feedback": {"D": "Check evaluates the results of the change.", "A": "Designing the trial and its measure is Plan.", "B": "Deciding to adopt, adjust or stop is Act.", "C": "Carrying out the trial is Do."}, "refs": ["R13", "R06"], "locator": "Module 2, §2.3 Plan–Do–Check–Act", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), PDCA cycle; ISO (n.d.), Quality management principles · Module 2, §2.3 Plan–Do–Check–Act", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q008", "module": 2, "objective": "M2-LO3", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: Results improved on similar flights. The team adopts the handover and adjusts one step that still caused waiting. Which PDCA stage is this?", "options": {"A": "Do", "B": "Check", "C": "Act", "D": "Plan"}, "answer": "C", "feedback": {"C": "Act adopts, adjusts or stops the change in light of the evidence.", "A": "Do was the trial on selected shifts.", "B": "Check compared the results; adopting and adjusting comes after it.", "D": "Plan designed the trial; this stage acts on the results."}, "refs": ["R13", "R06"], "locator": "Module 2, §2.3 Plan–Do–Check–Act", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), PDCA cycle; ISO (n.d.), Quality management principles · Module 2, §2.3 Plan–Do–Check–Act", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q009", "module": 2, "objective": "M2-LO3", "level": "Understand", "type": "MCQ", "question": "What happens in the Plan stage of PDCA?", "options": {"A": "Introduce the change on selected shifts", "B": "Design the trial and choose its measure", "C": "Decide whether to adopt, adjust or stop the change", "D": "Compare the results across similar flights"}, "answer": "B", "feedback": {"B": "Plan prepares the change and how it will be judged.", "A": "Introducing the change is Do.", "C": "This decision is Act.", "D": "Comparing results is Check."}, "refs": ["R13", "R06"], "locator": "Module 2, §2.3 Plan–Do–Check–Act", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), PDCA cycle; ISO (n.d.), Quality management principles · Module 2, §2.3 Plan–Do–Check–Act", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q010", "module": 2, "objective": "M2-LO4", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: Using the same definition of a late bag, period A had 15 late bags out of 1,500 and period B had 12 out of 800. What happened to the late-bag rate?", "options": {"A": "It rose from 1.0% to 1.5%", "B": "It cannot be compared, because volumes differed", "C": "It fell from 1.0% to 0.8%", "D": "It fell, because three fewer bags were late"}, "answer": "A", "feedback": {"A": "15 ÷ 1,500 = 1.0%; 12 ÷ 800 = 1.5%. Fewer bags were late, but a larger share.", "B": "Rates normalise for volume. The arithmetic comparison is valid here; interpreting performance also requires comparable operating conditions and reliable data.", "C": "Check the arithmetic: 12 ÷ 800 × 100 = 1.5%, not 0.8%.", "D": "This compares counts, not rates; volumes differed between the periods."}, "refs": ["R06"], "locator": "Module 2, §2.4 and worked example", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4 and worked example", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q011", "module": 2, "objective": "M2-LO4", "level": "Understand", "type": "MCQ", "question": "Which feature must a quality indicator have before its trend can be interpreted?", "options": {"A": "A colour-coded dashboard reviewed each month", "B": "A clear definition and a reliable data source", "C": "Approval by the accountable manager", "D": "A target set higher than last year's result to drive effort"}, "answer": "B", "feedback": {"B": "Without these you cannot tell what the numbers mean.", "A": "Presentation does not fix an undefined measure.", "C": "Approval does not establish what is measured or how reliably.", "D": "A target helps judge performance but does not make the data interpretable."}, "refs": ["R06"], "locator": "Module 2, §2.4 and worked example", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4 and worked example", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q012", "module": 2, "objective": "M2-LO4", "level": "Analyse", "type": "MCQ", "question": "Illustrative scenario: Customer complaints fell by 30% after a new online form replaced the service desk. What is the most defensible interpretation?", "options": {"A": "Complaints are unreliable, so they should no longer be collected", "B": "The fall may reflect the reporting change; check other measures", "C": "Service quality improved, because fewer customers complained", "D": "Service quality worsened, because the new form hides problems"}, "answer": "B", "feedback": {"B": "The reporting channel changed, which may have affected reporting behaviour. Check accessibility, customer exposure and other service measures before attributing the fall to service improvement.", "A": "Complaints remain useful; they need context, not removal.", "C": "A lower complaint count does not automatically establish better performance.", "D": "This is also an assumption; the evidence does not show which explanation is right."}, "refs": ["R06"], "locator": "Module 2, §2.4 and worked example", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4 and worked example", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q013", "module": 2, "objective": "M2-LO5", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: A new baggage procedure lowers the average delivery time, but very long delays become more frequent. What should the manager do before judging the change?", "options": {"A": "Wait for complaints to show whether passengers noticed", "B": "Examine the spread of times, including long delays", "C": "Reject the change, because some flights now perform worse", "D": "Accept the change, because the average shows overall improvement"}, "answer": "B", "feedback": {"B": "An average can hide a worsening tail of long delays.", "A": "Complaints are an indirect, delayed signal; the timing data are already available.", "C": "Rejecting it without analysis ignores the gain in average time.", "D": "The average alone hides the increase in long delays."}, "refs": ["R06"], "locator": "Module 2, §2.4 (averages and spread) and §2.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4 (averages and spread) and §2.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q014", "module": 2, "objective": "M2-LO5", "level": "Analyse", "type": "MCQ", "question": "Illustrative scenario: An improvement task to revise a baggage handover is marked closed. Which evidence best shows that the intended result was achieved?", "options": {"A": "Late-bag rates on similar flights stayed lower afterwards", "B": "All belt staff signed to confirm they read the procedure", "C": "The task owner reported the action complete on time", "D": "The revised handover procedure was approved and published"}, "answer": "A", "feedback": {"A": "Sustained improvement on comparable flights supports effectiveness. Also check data quality, adverse effects and other operational changes; before-and-after results alone do not prove causation.", "B": "Signatures show awareness, not the operational result.", "C": "Closing a task is different from verifying the intended result.", "D": "Approval shows the change was made, not that it worked."}, "refs": ["R06"], "locator": "Module 2, §2.5 Learning and improvement", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.5 Learning and improvement", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q015", "module": 2, "objective": "M2-LO5", "level": "Understand", "type": "True/False", "question": "Checking whether an improvement worked requires comparing results after the change, not only closing the task.", "options": {"A": "True", "B": "False"}, "answer": "A", "feedback": {"A": "Closing a task differs from verifying the intended operational result.", "B": "Not quite. A closed status records an administrative decision; implementation and effectiveness each require supporting evidence."}, "refs": ["R06"], "locator": "Module 2, §2.5 Learning and improvement", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.5 Learning and improvement", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q016", "module": 2, "objective": "M2-LO3", "level": "Apply", "type": "Matching", "question": "Illustrative scenario: A baggage team runs a handover trial. Match each PDCA stage to the activity that belongs to it.", "pairs": [["Plan", "Set a baseline and choose the measure for the trial"], ["Do", "Run the new handover on selected shifts"], ["Check", "Compare trial results with the baseline on similar flights"], ["Act", "Adopt the handover and adjust the step that still causes waiting"]], "distractors": ["Mark the task closed as soon as the procedure is approved"], "feedback": "Plan prepares the trial and how it will be judged; Do carries it out; Check compares results; Act adopts, adjusts or stops the change. Closing a task on approval is not a PDCA stage and does not verify the result.", "refs": ["R13", "R06"], "locator": "Module 2, §2.3 and §2.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ASQ (n.d.), PDCA cycle; ISO (n.d.), Quality management principles · Module 2, §2.3 and §2.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q017", "module": 2, "objective": "M2-LO4", "level": "Apply", "type": "Fill-in-the-blank", "question": "Illustrative scenario: Using the same definition of a delay, a station had 6 delayed turnarounds out of 120 in one month. The delay rate was ____ %.", "answers": ["5", "5.0", "5%", "5.0%"], "feedback": "6 ÷ 120 × 100 = 5%. A rate lets you compare periods with different numbers of turnarounds.", "refs": ["R06"], "locator": "Module 2, §2.4 and worked example", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4 and worked example", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M02-Q018", "module": 2, "objective": "M2-LO5", "level": "Analyse", "type": "Short answer", "question": "Illustrative case: a station trials a new baggage handover. Using the same definition of first-bag delivery time, the average fell from 24 to 22 minutes, but the number of flights with first-bag delivery taking more than 40 minutes rose from 2 to 6 per week. Total weekly flights are not provided. In three or four sentences, advise the manager what to check before judging the change and what evidence would support effectiveness.", "model_answer": "Obtain total flights for each period and compare the percentage exceeding 40 minutes; the count increase alone does not establish a worsening long-delay rate. Examine the distribution of first-bag delivery times and investigate where the longer delays occur. Compare a reliable baseline with comparable flights and conditions, checking other operational changes. Sustained improvement against agreed service criteria, without an unacceptable increase in the long-delay rate, would support effectiveness but would not by itself prove that the handover caused the change.", "marking_points": ["Requests total flights and calculates or proposes the proportion exceeding 40 minutes", "Looks beyond the average to the distribution and long delays", "Compares like with like: comparable flights, same definition, baseline", "Uses sustained results against agreed criteria, considers adverse effects and avoids claiming causation from before-and-after data alone"], "accept_note": "Accept equivalent, evidence-supported responses; the model answer is an example, not a required script.", "refs": ["R06"], "locator": "Module 2, §2.4–2.5, worked example and applied task model", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles · Module 2, §2.4–2.5, worked example and applied task model", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q001", "module": 3, "objective": "M3-LO1", "level": "Understand", "type": "MCQ", "question": "Which description best defines an audit?", "options": {"A": "A systematic, independent, documented process evaluating objective evidence against audit criteria", "B": "Any inspection a supervisor makes during a shift", "C": "A review of staff conduct to decide on discipline", "D": "An investigation to find the probable cause of an accident"}, "answer": "A", "feedback": {"A": "An audit gathers and objectively evaluates evidence against defined criteria through a systematic, independent and documented process. Criteria and evidence are necessary, but do not alone distinguish an audit from every other check. This is a teaching paraphrase, not a verbatim definition.", "B": "Not every inspection or monitoring activity is an audit.", "C": "An audit evaluates conformity with criteria; it is not a disciplinary review.", "D": "That is an accident investigation, such as the NTSB's, which has a different purpose."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.1–3.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.1–3.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q002", "module": 3, "objective": "M3-LO1", "level": "Remember", "type": "MCQ", "question": "In the Alaska Airlines Flight 1282 case, which organisation investigated the accident?", "options": {"A": "FAA", "B": "NTSB", "C": "Alaska Airlines", "D": "Boeing"}, "answer": "B", "feedback": {"B": "The NTSB investigated and determined the probable cause.", "A": "The FAA is the regulator; the NTSB examined its oversight as part of the investigation.", "C": "Alaska Airlines operated the flight; it did not lead the investigation.", "D": "Boeing was the manufacturer; its processes were examined by the investigation."}, "refs": ["R09"], "locator": "Module 3, §3.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "NTSB (2025), AIR-25-04 · Module 3, §3.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q003", "module": 3, "objective": "M3-LO1", "level": "Understand", "type": "MCQ", "question": "Why should the NTSB investigation of Flight 1282 not be described as an audit of Boeing?", "options": {"A": "It examined only Alaska Airlines' maintenance records", "B": "It was led by the FAA, which oversees Boeing's production", "C": "Its primary purpose was to establish causes and support prevention", "D": "It assessed conformity only against an agreed certification standard"}, "answer": "C", "feedback": {"C": "The NTSB investigation examined causes and circumstances to support prevention. It could examine compliance failures, but was not a management-system conformity audit.", "A": "The investigation examined manufacturing, training, records and oversight as well as operational circumstances.", "B": "The NTSB led the investigation; the FAA has a regulatory oversight role.", "D": "A safety investigation has a broader causal and preventive purpose than assessing conformity against a certification standard."}, "refs": ["R09"], "locator": "Module 3, §3.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "NTSB (2025), AIR-25-04 · Module 3, §3.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q004", "module": 3, "objective": "M3-LO2", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: Procedure IN-04 requires a signature on every completed inspection record. In an audit of IN-04, what is this requirement?", "options": {"A": "The criterion", "B": "The finding", "C": "The conclusion", "D": "The evidence"}, "answer": "A", "feedback": {"A": "The requirement is the reference against which evidence is evaluated.", "B": "A finding results from evaluating evidence against the criterion.", "C": "A conclusion summarises what the findings support within the audit scope.", "D": "Evidence is what the auditor observes, such as the sampled records."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.1–3.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.1–3.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q005", "module": 3, "objective": "M3-LO2", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: An auditor writes: “Against IN-04, record 07 of the ten Monday day-shift records sampled lacked the required signature.” What is this statement?", "options": {"A": "Audit evidence only", "B": "A finding", "C": "A criterion", "D": "An audit conclusion for all shifts"}, "answer": "B", "feedback": {"B": "It evaluates evidence (record 07) against the criterion (IN-04).", "A": "It goes beyond the observation by comparing it with the requirement.", "C": "The criterion is IN-04's requirement itself.", "D": "It is limited to the sample; it says nothing about other shifts."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.1–3.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.1–3.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q006", "module": 3, "objective": "M3-LO2", "level": "Analyse", "type": "MCQ", "question": "Illustrative scenario: An auditor sampled ten Monday day-shift records against IN-04 and found one unsigned. Which audit conclusion stays within the evidence?", "options": {"A": "Ten percent of all inspections in the organisation lack signatures", "B": "Night-shift records are probably complete, since none were sampled", "C": "The organisation has a record-keeping problem on all shifts", "D": "Within the Monday day-shift sample, IN-04 was not fully met"}, "answer": "D", "feedback": {"D": "A conclusion states the overall outcome, limited to the audit’s scope.", "A": "One sample from one shift cannot be extended to the whole organisation.", "B": "An unsampled shift supports no conclusion either way.", "C": "Other shifts were not sampled; they need their own evidence."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.1–3.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.1–3.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q007", "module": 3, "objective": "M3-LO3", "level": "Understand", "type": "MCQ", "question": "Which action is a correction rather than a corrective action?", "options": {"A": "Investigating why signatures are missed on several shifts", "B": "Sampling later records to see whether omissions stopped", "C": "Completing the incomplete record through the authorised correction process using traceable evidence", "D": "Revising the handover that repeatedly causes missed signatures"}, "answer": "C", "feedback": {"C": "A correction eliminates the detected nonconformity itself.", "A": "Investigating the cause is part of corrective action.", "B": "This is an effectiveness check of a corrective action.", "D": "This addresses the cause, so it is corrective action."}, "refs": ["R03", "R07"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q008", "module": 3, "objective": "M3-LO3", "level": "Understand", "type": "MCQ", "question": "What does corrective action address?", "options": {"A": "The cause or causes of a nonconformity, to prevent recurrence", "B": "The person who made the error, to deter others", "C": "The audit report, so that the finding can be closed", "D": "The single record found incomplete during the audit"}, "answer": "A", "feedback": {"A": "Corrective action addresses the cause or causes of a nonconformity to prevent recurrence. Correcting an individual record resolves the detected discrepancy; it does not necessarily remove its cause. This is a teaching explanation rather than a quoted ISO definition.", "B": "Corrective action addresses causes, which are often in the process, not deterrence.", "C": "Closing paperwork is not the aim; preventing recurrence is.", "D": "Fixing that record is a correction."}, "refs": ["R03", "R07"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q009", "module": 3, "objective": "M3-LO3", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: After revising the handover that caused missed signatures, which evidence best shows whether the corrective action worked?", "options": {"A": "The corrective-action register shows the item as closed", "B": "The revised procedure was approved by the quality manager", "C": "Later records from relevant shifts contain signatures", "D": "The original incomplete record was corrected and filed"}, "answer": "C", "feedback": {"C": "Representative later samples from relevant shifts, over an appropriate period, provide evidence about recurrence. Consider sample coverage and other changes; a few conforming records do not guarantee lasting effectiveness.", "A": "Closure in a register is not evidence of effectiveness.", "B": "Approval shows the change was made, not that it worked.", "D": "That was the correction; it says nothing about recurrence."}, "refs": ["R03", "R07"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q010", "module": 3, "objective": "M3-LO4", "level": "Remember", "type": "MCQ", "question": "Which assessment programme focuses primarily on ground-handling service providers?", "options": {"A": "IOSA", "B": "ISO 9001 certification", "C": "Competent-authority oversight", "D": "ISAGO"}, "answer": "D", "feedback": {"D": "IATA's ISAGO assesses ground-handling service providers.", "A": "IOSA assesses airline operational management and control systems.", "B": "ISO 9001 applies to any organisation; it is not specific to ground handling.", "C": "Regulatory oversight is a legal mandate, not an industry assessment programme."}, "refs": ["R10", "R11", "R12"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "IATA (n.d.), IOSA; IATA (n.d.), ISAGO; EASA (n.d.), Q&A Ground Handling Webinar 1 · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q011", "module": 3, "objective": "M3-LO4", "level": "Understand", "type": "MCQ", "question": "Which statement correctly distinguishes regulatory oversight from internal auditing?", "options": {"A": "Oversight reviews documents; internal audits review operations", "B": "Internal audit replaces oversight once certification is held", "C": "Both are the same activity, performed by different staff", "D": "Oversight is an authority duty; internal audit serves assurance"}, "answer": "D", "feedback": {"D": "They have different mandates.", "A": "Both can examine documents and operations; this is not the distinguishing feature.", "B": "Internal or industry audits do not transfer the competent authority’s oversight responsibility, although their evidence may inform oversight.", "C": "Similar techniques may be used, but the mandates differ."}, "refs": ["R07", "R12"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "EASA (2025), Easy Access Rules for Continuing Airworthiness; EASA (n.d.), Q&A Ground Handling Webinar 1 · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q012", "module": 3, "objective": "M3-LO4", "level": "Understand", "type": "True/False", "question": "ISAGO registration transfers the competent authority’s regulatory oversight responsibility to IATA.", "options": {"A": "True", "B": "False"}, "answer": "B", "feedback": {"B": "False. ISAGO does not transfer the authority’s oversight responsibility. Authorities may use industry audit information when planning or conducting their oversight.", "A": "Industry audit information may support oversight; responsibility remains with the competent authority."}, "refs": ["R10", "R11", "R12"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "IATA (n.d.), IOSA; IATA (n.d.), ISAGO; EASA (n.d.), Q&A Ground Handling Webinar 1 · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q013", "module": 3, "objective": "M3-LO5", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: A procedure requires completed inspection records to be retained and made available during audits. After checking the designated system and consulting the record owner, the organisation cannot provide one required record during the audit. What does this evidence establish?", "options": {"A": "The inspection was never carried out, so the part is unserviceable", "B": "The inspection was done, because the job was released afterwards", "C": "The availability requirement was not met; performance of the inspection needs further evidence", "D": "Nothing, because a missing record cannot support any finding"}, "answer": "C", "feedback": {"C": "The organisation could not provide the required record during the audit, supporting a finding against its availability requirement. This does not establish that the record was never created or that the inspection was not performed.", "A": "Non-availability does not prove the inspection was omitted or determine serviceability.", "B": "Job release alone does not prove every inspection step.", "D": "Failure to meet an explicit record-availability requirement can support a finding."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.4 Evidence and uncertainty", "group": "record-availability", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.4 Evidence and uncertainty", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q014", "module": 3, "objective": "M3-LO5", "level": "Understand", "type": "MCQ", "question": "What does a signed inspection record establish?", "options": {"A": "Conclusive proof that every step was carried out correctly", "B": "Relevant evidence, not conclusive proof of every step", "C": "Nothing useful, since signatures can be added after the work", "D": "Proof that the inspector was competent for the task"}, "answer": "B", "feedback": {"B": "A signature is documentary evidence with limits.", "A": "A signed record can be relevant evidence without proving every step.", "C": "Signed records are relevant evidence; their limits must simply be recognised.", "D": "A signature does not establish competence."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.4 Evidence and uncertainty", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.4 Evidence and uncertainty", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q015", "module": 3, "objective": "M3-LO5", "level": "Understand", "type": "True/False", "question": "Failure to provide a record required to be available during an audit can support a record-availability finding even if the underlying work may have been performed.", "options": {"A": "True", "B": "False"}, "answer": "A", "feedback": {"A": "True. The finding concerns the explicit availability requirement; whether the work occurred requires separate evidence.", "B": "Uncertainty about performance of the work does not remove the separate record-availability requirement."}, "refs": ["R05", "R02"], "locator": "Module 3, §3.4 Evidence and uncertainty", "group": "record-availability", "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.4 Evidence and uncertainty", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q016", "module": 3, "objective": "M3-LO2", "level": "Apply", "type": "Matching", "question": "Illustrative scenario: An auditor checks procedure IN-04. Match each audit term to the statement that illustrates it.", "pairs": [["Criterion", "IN-04 requires a signature on every completed inspection record"], ["Evidence", "Record 07 has an empty signature field"], ["Finding", "Record 07 does not meet IN-04’s recording requirement"], ["Conclusion", "Within the Monday day-shift sample, IN-04’s signature requirement was not fully met"]], "distractors": ["Night-shift records probably have the same gap"], "feedback": "The criterion is the requirement; evidence is what was observed; a finding is the result of comparing evidence with the criterion; a conclusion is the overall outcome drawn from the findings, limited to the audit scope. A claim about unsampled shifts is not supported.", "refs": ["R05", "R02"], "locator": "Module 3, §3.2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q017", "module": 3, "objective": "M3-LO3", "level": "Apply", "type": "Fill-in-the-blank", "question": "Illustrative scenario: An audit sample finds inspection record 07 without the required signature. The inspector who performed the check signs it through the authorised record-correction process, citing the work log. Later, the quality manager changes the shift handover so that signatures are no longer missed. The inspector’s action is a ____; the quality manager’s change is a corrective action.", "answers": ["correction", "a correction"], "feedback": "A correction addresses the detected nonconformity; corrective action addresses its cause or causes to prevent recurrence. Record corrections must follow the authorised process, preserve traceability and avoid unsupported reconstruction or backdating.", "refs": ["R03", "R07"], "locator": "Module 3, §3.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 9000:2026; EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 3, §3.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M03-Q018", "module": 3, "objective": "M3-LO5", "level": "Analyse", "type": "Short answer", "question": "Illustrative maintenance procedure WC-02 requires the specified wheel-fastener torque to be applied and the value, date and technician identifier to be recorded on a separate torque record. That record must be retained and available during audits. For wheel-change job W-017, the work order is signed as complete, but after checking the designated system and consulting the record owner, the organisation cannot provide the torque record during the audit. Write a finding against WC-02, state what the evidence does not establish, and identify one follow-up evidence source and its limitation.", "model_answer": "WC-02 requires torque records to be retained and available during audits; the organisation could not provide the record for W-017 after the stated checks, so the availability requirement was not met. This does not establish that the record was never created or that the fasteners were incorrectly tightened; the signed work order is relevant but not conclusive. Seek a dated, job-linked electronic torque-tool log, if available, and check its identity, completeness and traceability; a technician’s account can guide enquiries but should be corroborated. Any operational disposition belongs to the authorised maintenance function under applicable procedures.", "marking_points": ["Finding links job W-017 and the unavailable record to WC-02’s availability requirement", "States that the missing record does not prove the work was not done", "Recognises the signed work order as relevant but not conclusive", "Names relevant follow-up evidence and explains a limitation; wider sampling may assess scope but does not establish what happened on W-017"], "accept_note": "Accept equivalent, evidence-supported responses; the model answer is an example, not a required script.", "refs": ["R05", "R02"], "locator": "Module 3, §3.2 and §3.4 (scenario defined in the question)", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (2026), ISO 19011:2026; ASQ (n.d.), Quality assurance vs quality control · Module 3, §3.2 and §3.4 (scenario defined in the question)", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q001", "module": 4, "objective": "M4-LO1", "level": "Understand", "type": "MCQ", "question": "Which description best matches Just Culture as used in EU civil aviation?", "options": {"A": "Protection from any sanction for anyone who files a safety report", "B": "Fair accountability with limits, which encourages reporting", "C": "A policy that holds the organisation, not individuals, responsible", "D": "A rule that every reported error leads to a proportionate penalty"}, "answer": "B", "feedback": {"B": "Just Culture protects people from punishment for actions, omissions or decisions appropriate to their experience and training, while retaining boundaries: gross negligence, wilful violations and destructive acts are not tolerated. This teaching paraphrase follows Article 2(12); fair assessment of the circumstances remains necessary.", "A": "Just Culture does not mean that all conduct must be tolerated.", "C": "Individual accountability remains; it is judged fairly in context.", "D": "Automatic penalties discourage reporting; this is not Just Culture."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q002", "module": 4, "objective": "M4-LO1", "level": "Remember", "type": "MCQ", "question": "Which regulation's Article 2(12) defines Just Culture for EU civil aviation occurrence reporting?", "options": {"A": "Regulation (EU) 2018/1139", "B": "Regulation (EU) No 1321/2014", "C": "Regulation (EU) No 376/2014", "D": "Regulation (EU) No 965/2012"}, "answer": "C", "feedback": {"C": "Article 2(12) contains the definition.", "A": "Regulation 2018/1139 is the EASA Basic Regulation, not the occurrence-reporting regulation.", "B": "Regulation 1321/2014 covers continuing airworthiness, including Part-145, but does not contain this definition.", "D": "Regulation 965/2012 covers air operations."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q003", "module": 4, "objective": "M4-LO1", "level": "Understand", "type": "True/False", "question": "Just Culture means an organisation must tolerate any conduct once it has been reported.", "options": {"A": "True", "B": "False"}, "answer": "B", "feedback": {"B": "False. Reporting does not create unlimited immunity. Article 2(12) distinguishes actions consistent with experience and training from gross negligence, wilful violations and destructive acts.", "A": "Not quite. Just Culture does not mean all conduct is tolerated or that obligations can be ignored."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.1", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q004", "module": 4, "objective": "M4-LO2", "level": "Understand", "type": "MCQ", "question": "Why can automatic punishment of reported mistakes harm organisational learning?", "options": {"A": "Staff may stop reporting, so hazards stay hidden", "B": "Reports become too detailed to analyse properly", "C": "Investigations take longer to complete and cost more", "D": "Managers lose the authority to act on reports"}, "answer": "A", "feedback": {"A": "Fear of indiscriminate punishment discourages reporting.", "B": "Punishment tends to reduce reporting, not make reports too detailed.", "C": "The main harm is the information that is never reported.", "D": "Punishment does not remove managers' authority."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.2 Reporting and learning", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.2 Reporting and learning", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q005", "module": 4, "objective": "M4-LO2", "level": "Analyse", "type": "MCQ", "question": "Illustrative scenario: Reports rose by 40% after a new reporting app was introduced. What is the most defensible interpretation?", "options": {"A": "The app caused duplicate reports, explaining the increase", "B": "Reporting confidence has improved, so the change is positive", "C": "Operational safety has worsened and needs urgent action", "D": "Several explanations fit; more evidence is needed"}, "answer": "D", "feedback": {"D": "The count alone cannot distinguish these explanations.", "A": "Duplicates are a possible explanation to investigate, not an established explanation for the increase.", "B": "This also assumes one explanation without evidence.", "C": "This assumes one explanation; a new app was introduced, but its actual effect on reporting access and behaviour still needs investigation."}, "refs": ["R06", "R08"], "locator": "Module 4, §4.2 Reporting and learning", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles; Regulation (EU) No 376/2014, Art 2(12) · Module 4, §4.2 Reporting and learning", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q006", "module": 4, "objective": "M4-LO2", "level": "Understand", "type": "MCQ", "question": "Which practice most supports staff confidence to report?", "options": {"A": "Counting reports monthly without telling staff the outcome", "B": "Fair evaluation of reports with feedback to reporters", "C": "Rewarding teams that submit the fewest reports", "D": "Publishing reporters' names to show transparency"}, "answer": "B", "feedback": {"B": "Fair evaluation and feedback build trust.", "A": "Without feedback, staff cannot see that reporting leads to action.", "C": "This rewards silence and hides hazards.", "D": "Identifying reporters can deter reporting."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.2, §4.3 and §4.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.2, §4.3 and §4.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q007", "module": 4, "objective": "M4-LO3", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: A technician reports selecting an outdated task card before starting work. Which supervisor opening best reflects fair accountability?", "options": {"A": "“Since nothing happened, can we close the report now?”", "B": "“Who should have removed that card from the system?”", "C": "“Can you show me how you found the card and the mismatch?”", "D": "“You should have checked the revision before opening it.”"}, "answer": "C", "feedback": {"C": "It invites the sequence of events and recognises the recovery.", "A": "Recovery before work began does not remove the opportunity to learn.", "B": "Responsibility for document control may need examination, but opening with this question risks premature personal attribution before reconstructing events.", "D": "This presumes a failure before checking the required sequence and the circumstances."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.3, worked example and learning check 2", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.3, worked example and learning check 2", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q008", "module": 4, "objective": "M4-LO3", "level": "Understand", "type": "MCQ", "question": "What is the relationship between Just Culture and individual accountability?", "options": {"A": "Accountability remains and is judged fairly in context", "B": "Accountability transfers entirely from individuals to managers", "C": "Accountability applies only after a court reaches a verdict", "D": "Accountability is removed so that staff feel safe to report"}, "answer": "A", "feedback": {"A": "Accountability remains. Article 2(12) protects actions consistent with experience and training while excluding gross negligence, wilful violations and destructive acts; labels must not be assigned without a fair examination of the facts.", "B": "Both individual and organisational factors are considered.", "C": "Just Culture concerns fair evaluation within the organisation, not only court outcomes.", "D": "Just Culture does not remove accountability."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.1 and §4.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1 and §4.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q009", "module": 4, "objective": "M4-LO3", "level": "Understand", "type": "MCQ", "question": "When assessing a reported error fairly, which information should the supervisor consider?", "options": {"A": "How serious the outcome turned out to be, and nothing else", "B": "Whether colleagues think the person should be disciplined", "C": "Their training, experience and circumstances at the time", "D": "How many reports the person has submitted in the past year"}, "answer": "C", "feedback": {"C": "Relevant circumstances, experience and training must be considered.", "A": "Judging only by outcome ignores what the person knew and faced at the time.", "B": "Colleagues' opinions are not evidence about the event.", "D": "Reporting frequency says nothing about this event."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.1 and §4.3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1 and §4.3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q010", "module": 4, "objective": "M4-LO4", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: A technician reports opening an outdated task card. A colleague suggests that a cached copy on the workstation made the old revision appear, but no access route has yet been tested. How should the supervisor treat this suggestion?", "options": {"A": "As the established cause, since a colleague confirmed it", "B": "As irrelevant, because the technician selected the card", "C": "As sufficient grounds to close the report once the local cache is cleared", "D": "As a possible cause to test by reproducing the access path"}, "answer": "D", "feedback": {"D": "Inspect the workstation and reproduce the route before accepting a cause.", "A": "A suggested explanation is not an established cause; supporting observations or records are needed.", "B": "The circumstances explain how the old card was reachable; they matter.", "C": "Clearing the cache may be a useful containment step, but does not establish the cause or verify a lasting solution."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.3 and guided practice", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.3 and guided practice", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q011", "module": 4, "objective": "M4-LO4", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A ramp agent reports a loose baggage-cart latch. The supervisor examines the latch and photographs its loose condition. The maintenance history has not yet been checked. Which statement is directly supported by the scenario?", "options": {"A": "The supervisor photographed the loose latch", "B": "The cart was probably damaged during overnight towing", "C": "The ramp agent should have spotted it earlier", "D": "The last latch inspection was most likely missed"}, "answer": "A", "feedback": {"A": "This is directly observed and recorded.", "B": "This is a possible explanation still to be checked.", "C": "This is a judgement about the person, not a fact about the latch.", "D": "This is an assumption; the inspection record has not been obtained."}, "refs": ["R08", "R07"], "locator": "Module 4, applied decision (baggage-cart latch)", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, applied decision (baggage-cart latch)", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q012", "module": 4, "objective": "M4-LO4", "level": "Understand", "type": "True/False", "question": "Examining training, workstation access and the instructions visible at the time is part of evaluating a reported event fairly.", "options": {"A": "True", "B": "False"}, "answer": "A", "feedback": {"A": "Organisational conditions help explain the event and show what to fix.", "B": "Not quite. These conditions are relevant evidence for a fair evaluation."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.3 Accountability and context", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.3 Accountability and context", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q013", "module": 4, "objective": "M4-LO5", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: An employee submits a hazard report; managers add it to the monthly count but take no further action. What is missing?", "options": {"A": "An announcement of the report to all staff by email", "B": "A disciplinary review of the person who reported it", "C": "A higher monthly target for the number of reports", "D": "Risk evaluation, proportionate action and feedback"}, "answer": "D", "feedback": {"D": "Evaluation and follow-up turn information into learning.", "A": "Publicity is not a substitute for evaluation and action.", "B": "Discipline for reporting would discourage future reports.", "C": "A report count is not by itself a comprehensive safety indicator."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.4–4.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.4–4.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q014", "module": 4, "objective": "M4-LO5", "level": "Apply", "type": "MCQ", "question": "Illustrative scenario: The document owner removed an outdated task card from one workstation. Which follow-up best checks whether staff now reach the correct revision?", "options": {"A": "The owner confirms in writing that the copy was deleted", "B": "Staff on both shifts use normal access routes and verify that the current approved revision is retrieved", "C": "The quality manual is updated to mention outdated copies", "D": "The report is closed because the reporter was thanked"}, "answer": "B", "feedback": {"B": "Observed retrievals check whether normal access routes provide the current approved revision. Cover relevant workstations and repeat checks as appropriate; one successful retrieval does not establish that all old copies are inaccessible.", "A": "This confirms the action, not whether staff now reach the current revision.", "C": "Documentation does not show whether retrieval now works.", "D": "Thanking the reporter matters, but it does not verify the result."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.5 and learning check 3", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.5 and learning check 3", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q015", "module": 4, "objective": "M4-LO5", "level": "Understand", "type": "MCQ", "question": "Illustrative scenario: A technician reports opening an outdated task card before starting work. In addressing the event, how do QMS document controls and Just Culture most directly contribute?", "options": {"A": "The QMS handles reports; Just Culture controls revisions", "B": "They are one system described using two different names", "C": "Just Culture replaces the QMS once reporting is established", "D": "QMS controls revisions; Just Culture supports fair reporting"}, "answer": "D", "feedback": {"D": "Document controls help ensure access to current revisions; Just Culture supports reporting and fair assessment. A QMS may also include reporting and improvement processes, so these are complementary emphases rather than exclusive functions.", "A": "QMS processes may handle reports, but Just Culture does not itself control document revisions.", "B": "Just Culture is a cultural approach, not another name for a QMS.", "C": "Reporting does not replace document control or other QMS processes."}, "refs": ["R08", "R07"], "locator": "Module 4, §4.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.5", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q016", "module": 4, "objective": "M4-LO4", "level": "Apply", "type": "Matching", "question": "Illustrative case: a technician reports opening an old task card through a desktop shortcut before work began. The supervisor reproduces that access route and reaches the old revision. A colleague suggests a cached copy as the cause; this has not been tested. No night-shift access check has been made. Match each statement to its evidential status in this scenario.", "pairs": [["The supervisor reproduced the access route and reached the old revision", "Established fact"], ["The technician says the card was opened from a desktop shortcut", "Reported account"], ["A cached copy on the workstation may have caused the problem", "Possible explanation"], ["Which revision the shortcut points to on the night shift", "Information still needed"]], "distractors": ["Proof of individual negligence"], "feedback": "Separate what the supervisor observed, what was reported, what might explain it, and what still has to be checked. Nothing in the case establishes negligence; judging the person before examining the circumstances is not fair accountability.", "refs": ["R08", "R07"], "locator": "Module 4, §4.3, guided practice and applied task (baggage-cart latch)", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.3, guided practice and applied task (baggage-cart latch)", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q017", "module": 4, "objective": "M4-LO2", "level": "Apply", "type": "Fill-in-the-blank", "question": "Illustrative station data: in March, staff submitted 30 occurrence reports over 600 flights (5.0 reports per 100 flights). In April, after a new reporting app was introduced, they submitted 45 reports over 1,000 flights. In April there were ____ reports per 100 flights.", "answers": ["4.5", "4,5"], "feedback": "45 ÷ 1,000 × 100 = 4.5 reports per 100 flights. Reports increased by 50%, while flights increased by approximately 66.7%, so the reporting rate fell from 5.0 to 4.5 per 100 flights. This is an arithmetic comparison, not evidence that exposure caused the report increase. Neither the count nor the rate alone establishes a change in safety; reporting behaviour, event severity and operational context also matter.", "refs": ["R06", "R08"], "locator": "Module 4, §4.2 Reporting and learning; Module 2, worked example (rate per 100 flights)", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "ISO (n.d.), Quality management principles; Regulation (EU) No 376/2014, Art 2(12) · Module 4, §4.2 Reporting and learning; Module 2, worked example (rate per 100 flights)", "locator_status": "Checked against module text, 9 Nov 2026"}, {"id": "QMS-M04-Q018", "module": 4, "objective": "M4-LO3", "level": "Analyse", "type": "Short answer", "question": "Illustrative scenario: A manager proposes a written warning for the technician who opened an outdated task card, although the technician noticed the error and reported it before starting work. Using Just Culture, explain in two to four sentences why this response may harm learning and what the supervisor should do instead.", "model_answer": "Automatic punishment of a reported and recovered error can discourage staff from reporting, so the organisation loses information about how old cards remain reachable. Just Culture does not remove accountability, but conduct must be judged fairly in context. The supervisor should establish the sequence of events, examine the access path, training and instructions visible at the time, fix the document control problem, and tell the reporter what was changed and how it will be checked.", "marking_points": ["Explains that automatic punishment discourages reporting / hides hazards", "States that accountability remains but is judged fairly in context", "Proposes examining circumstances (access path, training, visible instructions)", "Includes feedback to the reporter and verification of the fix"], "accept_note": "Accept equivalent, evidence-supported responses; the model answer is an example, not a required script.", "refs": ["R08", "R07"], "locator": "Module 4, §4.1–4.5", "group": null, "status":"Lecturer-approved · v1.2 (9 Nov 2026)", "source": "Regulation (EU) No 376/2014, Art 2(12); EASA (2025), Easy Access Rules for Continuing Airworthiness · Module 4, §4.1–4.5", "locator_status": "Checked against module text, 9 Nov 2026"}];
